import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import {
  collection, doc, getDoc, getDocs, setDoc,
  updateDoc, query, where,
} from 'firebase/firestore';

const LOGIN_LOGO = "data:image/jpeg;base64,";

const BAN_IMG = "data:image/jpeg;base64,";

export function TelaBanida({ onVoltar }) {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', minHeight: '100vh', background: 'var(--bg)', padding: '24px' }}>
      <img src={BAN_IMG} alt="Conta banida" style={{ width: '100%', maxWidth: 360, borderRadius: 16, marginBottom: 32 }} />
      <button onClick={onVoltar}
        style={{ padding: '14px 32px', borderRadius: 14, border: '2px solid var(--cream)', background: 'transparent', color: 'var(--cream)', fontSize: 15, fontWeight: 700, fontFamily: 'var(--font-body)', letterSpacing: 2, textTransform: 'uppercase' }}>
        Voltar pro Login
      </button>
    </div>
  );
}

// ── Seed Mariana na primeira execução ─────────────────────────────────────────
async function seedMariana() {
  const ref  = doc(db, 'usuarios', 'mariana_gp');
  const snap = await getDoc(ref);
  if (!snap.exists()) {
    await setDoc(ref, {
      nome: 'Mariana', matricula: '202510853', senha: 'gp2026',
      cargo: 'Gestão de Pessoas', foto: null, xp: 0,
      status: 'ativo', criadoEm: new Date().toISOString(),
    });
  }
}

// ── Logo ──────────────────────────────────────────────────────────────────────
function Logo() {
  return (
    <div style={{ textAlign: 'center', marginBottom: 28 }}>
      <img
        src={LOGIN_LOGO}
        alt="NEnQ"
        style={{ width: '85%', maxWidth: 300, borderRadius: 16 }}
      />
    </div>
  );
}

// ── Tela de Login ─────────────────────────────────────────────────────────────
function TelaLogin({ onLogin, onCodigo }) {
  const [matricula, setMatricula] = useState('');
  const [senha, setSenha]         = useState('');
  const [senhaVis, setSenhaVis]   = useState(false);
  const [loading, setLoading]     = useState(false);
  const [erro, setErro]           = useState('');

  useEffect(() => { seedMariana().catch(() => {}); }, []);

  const entrar = async () => {
    if (!matricula || !senha) { setErro('Preencha todos os campos.'); return; }
    setLoading(true); setErro('');
    try {
      const q    = query(collection(db, 'usuarios'), where('matricula', '==', matricula.trim()));
      const snap = await getDocs(q);
      if (snap.empty) { setErro('Matrícula não encontrada.'); setLoading(false); return; }
      const user = { id: snap.docs[0].id, ...snap.docs[0].data() };
      if (user.status === 'banido') { onLogin({ ...user, banido: true }); return; }
      if (user.senha !== senha) { setErro('Senha incorreta.'); setLoading(false); return; }
      onLogin(user);
    } catch { setErro('Erro ao conectar. Tente novamente.'); setLoading(false); }
  };

  return (
    <div style={pageStyle}>
      <div style={{ position: 'absolute', top: -80, left: '50%', transform: 'translateX(-50%)', width: 300, height: 300, borderRadius: '50%', background: 'radial-gradient(circle, rgba(201,164,74,.09) 0%, transparent 70%)', pointerEvents: 'none' }} />
      <Logo />
      <div style={cardStyle}>
        <div style={{ fontFamily: 'var(--font-display)', fontSize: 20, fontWeight: 700, color: 'var(--cream)', marginBottom: 4 }}>Bem-vindo(a) 👋</div>
        <div style={{ fontSize: 13, color: 'var(--muted)', marginBottom: 22 }}>Entre com sua matrícula e senha</div>

        <label style={lbl}>Matrícula</label>
        <div style={{ position: 'relative', marginBottom: 14 }}>
          <span style={ico}>🎓</span>
          <input style={{ ...inp, paddingLeft: 38 }} type="number" placeholder="Ex: 202510853"
            value={matricula} onChange={e => { setMatricula(e.target.value); setErro(''); }} />
        </div>

        <label style={lbl}>Senha</label>
        <div style={{ position: 'relative', marginBottom: 6 }}>
          <span style={ico}>🔒</span>
          <input style={{ ...inp, paddingLeft: 38, paddingRight: 44 }}
            type={senhaVis ? 'text' : 'password'} placeholder="••••••••"
            value={senha} onChange={e => { setSenha(e.target.value); setErro(''); }}
            onKeyDown={e => e.key === 'Enter' && entrar()} />
          <button onClick={() => setSenhaVis(v => !v)}
            style={{ position: 'absolute', right: 12, top: '50%', transform: 'translateY(-50%)', background: 'none', border: 'none', fontSize: 16, opacity: .5 }}>
            {senhaVis ? '🙈' : '👁️'}
          </button>
        </div>

        {erro && <div style={erroStyle}>⚠️ {erro}</div>}

        <button onClick={entrar} disabled={loading} style={{ ...btnPrimary, marginTop: 20 }}>
          {loading ? '⏳ Verificando...' : 'Entrar →'}
        </button>
      </div>

      <div style={{ display: 'flex', alignItems: 'center', gap: 10, width: '100%', margin: '20px 0' }}>
        <div style={{ flex: 1, height: 1, background: 'var(--border)' }} />
        <span style={{ fontSize: 12, color: 'var(--muted)' }}>ou</span>
        <div style={{ flex: 1, height: 1, background: 'var(--border)' }} />
      </div>

      <button onClick={onCodigo} style={btnSecondary}>
        🔑 Tenho um código de acesso
      </button>
    </div>
  );
}

// ── Tela de Código de Acesso ──────────────────────────────────────────────────
function TelaCodigo({ onVoltar, onLogin }) {
  const [codigo, setCodigo]   = useState('');
  const [senha, setSenha]     = useState('');
  const [confirmSenha, setConfirmSenha] = useState('');
  const [etapa, setEtapa]     = useState(1); // 1=código, 2=criar senha
  const [dadosCodigo, setDadosCodigo] = useState(null);
  const [loading, setLoading] = useState(false);
  const [erro, setErro]       = useState('');

  // Recupera código pendente salvo
  useEffect(() => {
    try {
      const saved = localStorage.getItem('nenq_codigo_pendente');
      if (saved) setCodigo(saved);
    } catch {}
  }, []);

  const verificarCodigo = async () => {
    if (!codigo.trim()) { setErro('Digite o código.'); return; }
    setLoading(true); setErro('');
    try {
      const q    = query(collection(db, 'codigos_acesso'),
        where('codigo', '==', codigo.trim().toUpperCase()),
        where('usado', '==', false));
      const snap = await getDocs(q);
      if (snap.empty) { setErro('Código inválido ou já utilizado.'); setLoading(false); return; }
      const data = { id: snap.docs[0].id, ...snap.docs[0].data() };
      setDadosCodigo(data);
      try { localStorage.setItem('nenq_codigo_pendente', codigo.trim().toUpperCase()); } catch {}
      setEtapa(2);
      setLoading(false);
    } catch { setErro('Erro ao verificar. Tente novamente.'); setLoading(false); }
  };

  const criarSenha = async () => {
    if (!senha || !confirmSenha) { setErro('Preencha todos os campos.'); return; }
    if (senha.length < 6) { setErro('Senha deve ter pelo menos 6 caracteres.'); return; }
    if (senha !== confirmSenha) { setErro('As senhas não coincidem.'); return; }
    setLoading(true); setErro('');
    try {
      // Criar usuário
      const userRef = doc(collection(db, 'usuarios'));
      await setDoc(userRef, {
        nome: dadosCodigo.nome, matricula: dadosCodigo.matricula,
        cargo: dadosCodigo.cargo, foto: dadosCodigo.foto || null,
        senha, xp: 0, status: 'ativo', criadoEm: new Date().toISOString(),
      });
      // Marcar código como usado
      await updateDoc(doc(db, 'codigos_acesso', dadosCodigo.id), { usado: true });
      try { localStorage.removeItem('nenq_codigo_pendente'); } catch {}
      onLogin({ id: userRef.id, nome: dadosCodigo.nome, matricula: dadosCodigo.matricula, cargo: dadosCodigo.cargo, foto: dadosCodigo.foto || null, xp: 0 });
    } catch { setErro('Erro ao criar conta. Tente novamente.'); setLoading(false); }
  };

  return (
    <div style={pageStyle}>
      <Logo />
      <div style={cardStyle}>
        {etapa === 1 ? (
          <>
            <div style={{ fontFamily: 'var(--font-display)', fontSize: 20, fontWeight: 700, color: 'var(--cream)', marginBottom: 4 }}>Código de acesso 🔑</div>
            <div style={{ fontSize: 13, color: 'var(--muted)', marginBottom: 22 }}>Digite o código recebido da equipe NEnQ</div>
            <label style={lbl}>Código (6 dígitos)</label>
            <div style={{ position: 'relative', marginBottom: 6 }}>
              <span style={ico}>🔑</span>
              <input
                style={{ ...inp, paddingLeft: 38, textTransform: 'uppercase', letterSpacing: 6, fontSize: 20, fontWeight: 700, textAlign: 'center' }}
                type="text" placeholder="AB12CD" maxLength={6}
                value={codigo} onChange={e => { setCodigo(e.target.value.toUpperCase()); setErro(''); }} />
            </div>
            {erro && <div style={erroStyle}>⚠️ {erro}</div>}
            <button onClick={verificarCodigo} disabled={loading} style={{ ...btnPrimary, marginTop: 20 }}>
              {loading ? '⏳ Verificando...' : 'Verificar código →'}
            </button>
          </>
        ) : (
          <>
            <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 20, padding: '12px', background: 'var(--bg)', borderRadius: 12 }}>
              {dadosCodigo?.foto
                ? <img src={dadosCodigo.foto} alt="" style={{ width: 48, height: 48, borderRadius: '50%', objectFit: 'cover', border: '2px solid var(--gold)' }} />
                : <div style={{ width: 48, height: 48, borderRadius: '50%', background: 'var(--bg3)', border: '2px solid var(--gold)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: 'var(--font-display)', fontSize: 18, fontWeight: 700, color: 'var(--gold)' }}>{dadosCodigo?.nome?.[0]}</div>
              }
              <div>
                <div style={{ fontSize: 15, fontWeight: 700, color: 'var(--cream)' }}>{dadosCodigo?.nome}</div>
                <div style={{ fontSize: 12, color: 'var(--gold)', marginTop: 2 }}>{dadosCodigo?.cargo}</div>
                <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 1 }}>Matrícula: {dadosCodigo?.matricula}</div>
              </div>
            </div>
            <div style={{ fontFamily: 'var(--font-display)', fontSize: 18, fontWeight: 700, color: 'var(--cream)', marginBottom: 4 }}>Crie sua senha 🔐</div>
            <div style={{ fontSize: 13, color: 'var(--muted)', marginBottom: 18 }}>Olá {dadosCodigo?.nome?.split(' ')[0]}! Crie sua senha de acesso.</div>

            <label style={lbl}>Nova senha</label>
            <div style={{ position: 'relative', marginBottom: 14 }}>
              <span style={ico}>🔒</span>
              <input style={{ ...inp, paddingLeft: 38 }} type="password" placeholder="Mínimo 6 caracteres"
                value={senha} onChange={e => { setSenha(e.target.value); setErro(''); }} />
            </div>

            <label style={lbl}>Confirmar senha</label>
            <div style={{ position: 'relative', marginBottom: 6 }}>
              <span style={ico}>🔒</span>
              <input style={{ ...inp, paddingLeft: 38 }} type="password" placeholder="Repita a senha"
                value={confirmSenha} onChange={e => { setConfirmSenha(e.target.value); setErro(''); }} />
            </div>
            {erro && <div style={erroStyle}>⚠️ {erro}</div>}
            <button onClick={criarSenha} disabled={loading} style={{ ...btnPrimary, marginTop: 20 }}>
              {loading ? '⏳ Criando conta...' : 'Entrar no NEnQ →'}
            </button>
          </>
        )}
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, width: '100%', margin: '20px 0' }}>
        <div style={{ flex: 1, height: 1, background: 'var(--border)' }} />
      </div>
      <button onClick={() => { try { localStorage.removeItem('nenq_codigo_pendente'); } catch {} onVoltar(); }} style={btnSecondary}>
        ← Voltar ao login
      </button>
    </div>
  );
}

// ── Componente Principal ──────────────────────────────────────────────────────
export default function LoginScreen({ onLogin }) {
  const hasPendingCode = (() => { try { return !!localStorage.getItem('nenq_codigo_pendente'); } catch { return false; } })();
  const [tela, setTela] = useState(hasPendingCode ? 'codigo' : 'login');

  if (tela === 'codigo') return <TelaCodigo onVoltar={() => setTela('login')} onLogin={onLogin} />;
  return <TelaLogin onLogin={onLogin} onCodigo={() => setTela('codigo')} />;
}

// ── Estilos ───────────────────────────────────────────────────────────────────
const pageStyle  = { display: 'flex', flexDirection: 'column', minHeight: '100vh', background: 'var(--bg)', alignItems: 'center', padding: '40px 24px 32px', position: 'relative', overflow: 'hidden' };
const cardStyle  = { width: '100%', background: 'var(--bg3)', border: '1px solid var(--border2)', borderRadius: 24, padding: '24px 20px', boxShadow: '0 8px 40px rgba(0,0,0,.3)' };
const lbl        = { display: 'block', fontSize: 12, fontWeight: 700, color: 'var(--cream)', opacity: .55, marginBottom: 6, letterSpacing: '.05em', textTransform: 'uppercase' };
const inp        = { width: '100%', background: 'var(--card)', border: '1px solid var(--border2)', borderRadius: 12, padding: '12px 14px', fontSize: 15, color: 'var(--cream)', fontFamily: 'var(--font-body)', outline: 'none', boxSizing: 'border-box' };
const ico        = { position: 'absolute', left: 13, top: '50%', transform: 'translateY(-50%)', fontSize: 16, opacity: .5 };
const erroStyle  = { fontSize: 13, color: '#e87f7f', margin: '10px 0 0', padding: '9px 13px', background: 'rgba(232,127,127,.1)', borderRadius: 10, border: '1px solid rgba(232,127,127,.2)' };
const btnPrimary = { width: '100%', padding: '14px', borderRadius: 14, border: 'none', cursor: 'pointer', background: 'linear-gradient(135deg,#C9A44A 0%,#a8832e 100%)', color: 'var(--bg)', fontSize: 15, fontWeight: 700, fontFamily: 'var(--font-body)', boxShadow: '0 4px 16px rgba(201,164,74,.3)' };
const btnSecondary = { width: '100%', padding: '14px', borderRadius: 14, border: '1px solid var(--border2)', cursor: 'pointer', background: 'transparent', color: 'var(--cream)', fontSize: 14, fontWeight: 600, fontFamily: 'var(--font-body)' };
